    function getDateTimeText(utcDateString) {
      var year = utcDateString.substring(0, 4);
      var month = utcDateString.substring(5, 7);
      var day = utcDateString.substring(8, 10);
      var minute = utcDateString.substring(14, 16);
      var hour = utcDateString.substring(11, 13);
      return hour + ":" + minute + " del " + day + "/" + month + "/" + year;
    }

    function getDateText(utcDateString) {
      var year = utcDateString.substring(0, 4);
      var month = utcDateString.substring(5, 7);
      var day = utcDateString.substring(8, 10);
      return day + "/" + month + "/" + year;
    }

    function getTimeText(utcDateString) {
      var minute = utcDateString.substring(14, 16);
      var hour = utcDateString.substring(11, 13);
      return hour + ":" + minute;
    }

