    function fnUserFavoritesGet() {
      if (
        localStorage.getItem("Guid") == "" ||
        localStorage.getItem("Guid") == undefined ||
        localStorage.getItem("Guid") == null
      ) {
        return false;
      }
      $.ajax({
        url: urlFunctionMyFit + "/api/v2/tournament/favourite/list",
        type: "POST",
        dataType: "json",
        data: JSON.stringify({
          guid: String(localStorage.getItem("Guid")),
          member: String(localStorage.getItem("Member")),
          teacher: String(localStorage.getItem("Teacher")),
          udg: String(localStorage.getItem("Udg")),
          acceptProfilation: String(localStorage.getItem("AcceptProfilation")),
          hashKey: String(localStorage.getItem("Hashkey")),
        }),
        contentType: "application/json; charset=utf-8",
        success: function (res) {
          fnUserFavoritesActivate(res);
        },
      });
    }

    function fnUserFavoritesActivate(res) {
      if (res == "" || res == undefined || res == null) {
        return false;
      } else {
        $(".cc-favorite-off").hide();
        $(".cc-favorite-off").removeAttr("data-guidfavorite");
        $(".cc-favorite-on").show();
        $.each(res.favouriteTournaments, function (i, item) {
          if (
            parseInt(idDisciplina) ==
              parseInt(res.favouriteTournaments[i].discipline) &&
            String(GetParameterValues("competitionId")).toUpperCase() ==
              String(res.favouriteTournaments[i].uid).toUpperCase() &&
            parseInt(res.favouriteTournaments[i].type) == 1
          ) {
            $(".cc-favorite-on").hide();
            $(".cc-favorite-off").attr(
              "data-guidfavorite",
              res.favouriteTournaments[i].guid
            );
            $(".cc-favorite-off").show();
          }
        });
      }
    }

    function checkSubscribeTemporaryToTournament() {
      $.ajax({
        //url: "https://dp-fit-prod-function.azurewebsites.net/api/v6/myfit/tournaments/sgat/player/status/get",
        url: urlFunctionMyFit + "/api/v2/tesserato/tornei-doppi/status/get",
        type: "POST",
        dataType: "json",
        data: JSON.stringify({
          guid: String(localStorage.getItem("Guid")),
          member: String(localStorage.getItem("Member")),
          teacher: String(localStorage.getItem("Teacher")),
          udg: String(localStorage.getItem("Udg")),
          acceptProfilation: String(localStorage.getItem("AcceptProfilation")),
          hashKey: String(localStorage.getItem("Hashkey")),
          tournamentId: String(uidTournamentSelected),
          tournamentYear: tournamentYear,
          tournamentMonth: tournamentMonth,
          discipline: idDisciplina,
        }),
        contentType: "application/json; charset=utf-8",
        success: function (res) {
          if (res.statusCode === 200) {
            popupSearchPlayerSubscribeToTournament();
          } else if (res.statusCode === 402) {
            if (
              res.error ==
              "La tua sessione è scaduta, effettua nuovamente il login."
            ) {
              localStorage.clear();

              showPopUpSubscriptionError(res.error);

              window.location.href = site_url + "/?logout=1";
              return false;
            } else {
              showPopUpSubscriptionError(res.error);
            }
          } else if (res.statusCode === 403) {
            showPopUpSubscriptionError(res.error);
          } else if (res.statusCode === 405) {
            showPopUpSubscriptionError(res.error);
            tournamentSubscriptionCheck();
          } else {
            showPopUpSubscriptionError(res.error);
          }
        },
        error: function (data) {
          let msg = data.responseJSON.error;
          if (msg != null && msg != "") {
            showPopUpAlert("ko", "Errore", msg);
          } else {
            showPopUpAlert(
              "ko",
              "Errore",
              "L'operazione non è andata a buon fine"
            );
          }
        },
      });
    }

