    function paginatePartecipants() {
      // because pages logically start with 1, but technically with 0
      $("#spn-partial-player-count").text(0);
      $("#spn-total-player-count").text(0);
      $("#btnLoadMore").hide();
      if (selectedTournament.Participants !== null) {
        var partecipantsTmp = JSLINQ(selectedTournament.Participants);

        switch (partecipantsOrderField) {
          case "surname":
            if (partecipantsOrderVerso == "asc")
              var result = partecipantsTmp
                .OrderBy(function (el) {
                  return el.Surname;
                })
                .ToArray();
            else
              var result = partecipantsTmp
                .OrderByDescending(function (el) {
                  return el.Surname;
                })
                .ToArray();
            break;
          case "ranking":
            if (partecipantsOrderVerso == "desc")
              var result = partecipantsTmp
                .OrderBy(function (el) {
                  return el.Ranking;
                })
                .ToArray();
            else
              var result = partecipantsTmp
                .OrderByDescending(function (el) {
                  return el.Ranking;
                })
                .ToArray();
            break;
          case "datesubscription":
            if (partecipantsOrderVerso == "desc")
              var result = partecipantsTmp
                .OrderByDescending(function (el) {
                  //console.log(el.Surname + ' - ' + el.SubscriptionDate);
                  var d1 = new Date(el.SubscriptionDate);
                  //console.log(d1);
                  var t1 = d1.getTime();
                  //console.log(t1);
                  return t1;
                })
                .ToArray();
            else
              var result = partecipantsTmp
                .OrderBy(function (el) {
                  //console.log(el.Surname + ' - ' + el.SubscriptionDate);
                  var d1 = new Date(el.SubscriptionDate);
                  //console.log(d1);
                  var t1 = d1.getTime();
                  //console.log(t1);
                  return t1;
                })
                .ToArray();
            break;
        }

        $("#spn-total-player-count").text(
          selectedTournament.Participants.length
        );

        //var paginatedPartecipants = selectedTournament.Participants.slice(selectedPage * 20, (selectedPage + 1) * 20);
        if (partecipantsPaginateTmp == 0)
          partecipantsPaginateTmp = partecipantsPaginate;
        var paginatedPartecipants = result.slice(
          selectedPage * partecipantsPaginateTmp,
          (selectedPage + 1) * partecipantsPaginateTmp
        );
        for (var i = 0; i < paginatedPartecipants.length; i++) {
          appendSinglePlayer(paginatedPartecipants[i]);
        }

        //partecipantsPaginateTmp = partecipantsPaginate;

        selectedPage++;
      }
    }

